import{i as e,n as t,r as n,t as r}from"./index-4qcVfKL9.js";var i={},a={class:`container my-5`};function o(r,i){return e(),t(`div`,a,[...i[0]||=[n(`<div class="card shadow-sm p-4 mb-4 bg-light border-0"><div class="row align-items-center"><div class="col-md-8"><h3>Službena dokumentacija</h3><p class="text-muted mb-0"> Preuzmite PDF dokument s potpunom specifikacijom projekta. </p></div><div class="col-md-4 text-md-end mt-3 mt-md-0"><a href="/vizija.pdf" download="vizija.pdf" class="btn btn-primary"><i class="bi bi-file-earmark-arrow-down-fill me-2"></i> Preuzmi PDF dokument </a></div></div></div><h1 class="mb-4">Vizija projekta - Sustav za instrukcije</h1><h3 class="text-secondary">Cilj projekta</h3><p> Cilj ovog projekta je izrada moderne web aplikacije koja omogućuje jednostavno upravljanje, zakazivanje i rezervaciju instrukcija. Aplikacija povezuje studente, instruktore i administratore u jedinstven sustav koji olakšava proces pronalaska slobodnih termina, prijave na instrukcije i administrativnog nadzora. </p><h3 class="mt-4">Svrha i ciljevi</h3><ul><li> Omogućiti studentima jednostavno pretraživanje i rezervaciju termina instrukcija prema predmetima. </li><li> Povezati instruktore i studente kroz sustav upravljanja zahtjevima i radnim kalendarom. </li><li> Podržati napredne funkcionalnosti poput WYSIWYG uređivanja napomena, priloga te ispisa. </li><li> Omogućiti administratorima potpun nadzor nad korisnicima, ulogama, predmetima i terminima. </li></ul><h3 class="mt-4">Korisničke uloge</h3><p><strong>Administrator:</strong> Upravlja korisnicima, dodaje/uređuje predmete i ima uvid u cijeli sustav. </p><p><strong>Instruktor:</strong> Unosi slobodne termine, definira cijene i upravlja pristiglim zahtjevima za rezervacije. </p><p><strong>Student:</strong> Pregledava termine, šalje zahtjeve za rezervaciju s napomenama i privitcima te prati status svojih rezervacija. </p>`,10)]])}var s=r(i,[[`render`,o]]);export{s as default};